import io
import os
import textwrap
import zipfile
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Any, Dict, Iterable, List, Optional, Tuple

import pandas as pd
import viktor as vkt

import ifcopenshell
import ifcopenshell.util.element


# ----------------------
# IFC helpers
# ----------------------


def _as_viktor_file(file_field_value: Any) -> Optional[vkt.File]:
    """VIKTOR's FileField value may either be a vkt.File, or an object with `.file`.

    This helper makes the app compatible across multiple VIKTOR versions.
    """
    if not file_field_value:
        return None
    return getattr(file_field_value, "file", file_field_value)


def _get_file_bytes(file: vkt.File) -> bytes:
    """Return raw bytes from a VIKTOR File."""
    if hasattr(file, "getvalue_binary"):
        try:
            return file.getvalue_binary()
        except Exception:
            pass
    # Fallback (IFC is usually text)
    text = file.getvalue() if hasattr(file, "getvalue") else str(file)
    return text.encode("utf-8", errors="ignore")


def _extract_ifc_bytes(raw: bytes) -> bytes:
    """Return IFC bytes from either an .ifc file, or a zipped IFC (.ifczip / .zip)."""
    if len(raw) >= 2 and raw[:2] == b"PK":
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            # Prefer files that look like IFC
            candidates = [n for n in zf.namelist() if n.lower().endswith(".ifc")]
            if not candidates:
                # Some tools zip without .ifc extension
                candidates = list(zf.namelist())
            if not candidates:
                raise vkt.UserError("ZIP file does not contain any files.")
            # Take the first IFC-like file
            return zf.read(candidates[0])
    return raw


def _open_ifc_model_from_bytes(ifc_bytes: bytes) -> ifcopenshell.file:
    """Open IFC in IfcOpenShell by writing to a temporary file."""
    tmp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp.write(ifc_bytes)
            tmp_path = tmp.name
        return ifcopenshell.open(tmp_path)
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass


def _safe_str(value: Any) -> str:
    return "" if value is None else str(value)


def _first_nonempty(*values: Any) -> Any:
    for v in values:
        if v is None:
            continue
        if isinstance(v, str) and v.strip() == "":
            continue
        if isinstance(v, (int, float)) and float(v) == 0.0:
            continue
        return v
    return None


def _length_unit_scale_to_m(model: ifcopenshell.file) -> float:
    """Return factor to convert model length units to meters.

    - If model unit is millimeters: returns 0.001
    - If model unit is meters: returns 1.0

    For uncommon units we fall back to 1.0 (meters).
    """
    try:
        project = model.by_type("IfcProject")[0]
        units = project.UnitsInContext.Units if project.UnitsInContext else []
        for u in units:
            if not getattr(u, "UnitType", None) == "LENGTHUNIT":
                continue

            # IFC SI units
            if u.is_a("IfcSIUnit"):
                # Name is usually METRE
                prefix = getattr(u, "Prefix", None)
                name = (getattr(u, "Name", None) or "").upper()
                if "METRE" in name:
                    if prefix is None:
                        return 1.0
                    prefix = str(prefix).upper()
                    return {
                        "MILLI": 0.001,
                        "CENTI": 0.01,
                        "DECI": 0.1,
                        "DECA": 10.0,
                        "HECTO": 100.0,
                        "KILO": 1000.0,
                    }.get(prefix, 1.0)

            # Conversion based units (e.g., FOOT)
            if u.is_a("IfcConversionBasedUnit"):
                cf = getattr(u, "ConversionFactor", None)
                if cf and getattr(cf, "ValueComponent", None):
                    vc = cf.ValueComponent
                    val = getattr(vc, "wrappedValue", None)
                    if val is not None:
                        return float(val)
    except Exception:
        pass
    return 1.0


def _convert_length(
    value_in_model_units: Optional[float],
    *,
    scale_to_m: float,
    out_unit: str,
) -> Optional[float]:
    if value_in_model_units is None:
        return None
    try:
        v = float(value_in_model_units)
    except Exception:
        return None

    if out_unit == "Model":
        return v

    v_m = v * scale_to_m
    if out_unit == "m":
        return v_m
    if out_unit == "mm":
        return v_m * 1000.0
    if out_unit == "ft":
        return v_m * 3.280839895

    return v


def _format_length(val: Optional[float], decimals: int = 0) -> Optional[float]:
    if val is None:
        return None
    try:
        return round(float(val), decimals)
    except Exception:
        return None


def _get_type_name(element: Any) -> str:
    try:
        t = ifcopenshell.util.element.get_type(element)
        if t is None:
            return ""
        return _safe_str(getattr(t, "Name", ""))
    except Exception:
        return ""


def _get_level_name(element: Any) -> str:
    """Try to get the IfcBuildingStorey name."""
    try:
        container = ifcopenshell.util.element.get_container(element)
        if container and container.is_a("IfcBuildingStorey"):
            return _safe_str(container.Name)
        # Sometimes container is a space, which itself belongs to a storey
        if container and container.is_a("IfcSpace"):
            storey = ifcopenshell.util.element.get_container(container)
            if storey and storey.is_a("IfcBuildingStorey"):
                return _safe_str(storey.Name)
    except Exception:
        pass
    return ""


def _get_overall_dimensions(element: Any) -> Tuple[Optional[float], Optional[float]]:
    """Extract width/height in model units.

    Priority:
    1) IfcDoor/IfcWindow OverallWidth/OverallHeight
    2) Qto_*BaseQuantities Width/Height
    3) Common Pset fields (varies by authoring tool)
    """
    width = _first_nonempty(getattr(element, "OverallWidth", None))
    height = _first_nonempty(getattr(element, "OverallHeight", None))

    # Quantities can be stored under different Qto names
    if width is None or height is None:
        for qto_name in (
            "Qto_DoorBaseQuantities",
            "Qto_WindowBaseQuantities",
            "Qto_DoorQuantities",
            "Qto_WindowQuantities",
        ):
            if width is None:
                width = _first_nonempty(
                    ifcopenshell.util.element.get_pset(element, qto_name, "Width"),
                    ifcopenshell.util.element.get_pset(element, qto_name, "OverallWidth"),
                )
            if height is None:
                height = _first_nonempty(
                    ifcopenshell.util.element.get_pset(element, qto_name, "Height"),
                    ifcopenshell.util.element.get_pset(element, qto_name, "OverallHeight"),
                )

    # Some tools push dimensions into Pset_...Common
    if width is None:
        width = _first_nonempty(
            ifcopenshell.util.element.get_pset(element, "Pset_DoorCommon", "OverallWidth"),
            ifcopenshell.util.element.get_pset(element, "Pset_WindowCommon", "OverallWidth"),
            ifcopenshell.util.element.get_pset(element, "Pset_DoorCommon", "Width"),
            ifcopenshell.util.element.get_pset(element, "Pset_WindowCommon", "Width"),
        )

    if height is None:
        height = _first_nonempty(
            ifcopenshell.util.element.get_pset(element, "Pset_DoorCommon", "OverallHeight"),
            ifcopenshell.util.element.get_pset(element, "Pset_WindowCommon", "OverallHeight"),
            ifcopenshell.util.element.get_pset(element, "Pset_DoorCommon", "Height"),
            ifcopenshell.util.element.get_pset(element, "Pset_WindowCommon", "Height"),
        )

    try:
        width = float(width) if width is not None else None
    except Exception:
        width = None
    try:
        height = float(height) if height is not None else None
    except Exception:
        height = None

    return width, height


def _build_space_boundary_map(model: ifcopenshell.file) -> Dict[str, List[str]]:
    """Map element GlobalId -> list of adjacent IfcSpace names (via IfcRelSpaceBoundary)."""
    space_map: Dict[str, List[str]] = defaultdict(list)
    try:
        rels = model.by_type("IfcRelSpaceBoundary")
    except Exception:
        rels = []

    for rel in rels:
        try:
            elem = getattr(rel, "RelatedBuildingElement", None)
            space = getattr(rel, "RelatingSpace", None)
            if not elem or not space:
                continue
            gid = getattr(elem, "GlobalId", None)
            if not gid:
                continue
            space_name = _first_nonempty(getattr(space, "LongName", None), getattr(space, "Name", None))
            if not space_name:
                continue
            # Unique, stable ordering
            if space_name not in space_map[gid]:
                space_map[gid].append(space_name)
        except Exception:
            continue

    # Stable, deterministic order
    for gid in list(space_map.keys()):
        space_map[gid] = sorted(space_map[gid])

    return dict(space_map)


@dataclass
class ScheduleOptions:
    include_spaces: bool
    out_unit: str  # Model, mm, m, ft


def _get_doors_and_windows_schedule(
    ifc_bytes: bytes,
    *,
    options: ScheduleOptions,
) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """Return (schedule_df, meta)."""
    model = _open_ifc_model_from_bytes(ifc_bytes)

    scale_to_m = _length_unit_scale_to_m(model)

    # Optional room/space adjacency
    space_map: Dict[str, List[str]] = {}
    if options.include_spaces:
        space_map = _build_space_boundary_map(model)

    rows: List[Dict[str, Any]] = []

    elements = []
    elements.extend(model.by_type("IfcDoor"))
    elements.extend(model.by_type("IfcWindow"))

    for e in elements:
        cls = e.is_a()
        gid = _safe_str(getattr(e, "GlobalId", ""))
        name = _safe_str(getattr(e, "Name", ""))
        tag = _safe_str(getattr(e, "Tag", ""))
        obj_type = _safe_str(getattr(e, "ObjectType", ""))
        predefined_type = _safe_str(getattr(e, "PredefinedType", ""))

        type_name = _get_type_name(e)
        level_name = _get_level_name(e)

        w_raw, h_raw = _get_overall_dimensions(e)
        w = _format_length(_convert_length(w_raw, scale_to_m=scale_to_m, out_unit=options.out_unit), decimals=0)
        h = _format_length(_convert_length(h_raw, scale_to_m=scale_to_m, out_unit=options.out_unit), decimals=0)

        spaces = space_map.get(gid, []) if gid else []
        space_1 = spaces[0] if len(spaces) > 0 else ""
        space_2 = spaces[1] if len(spaces) > 1 else ""

        # Common schedule fields
        rows.append(
            {
                "Category": "Door" if cls == "IfcDoor" else "Window",
                "GlobalId": gid,
                "Name": name,
                "Tag": tag,
                "Type": type_name,
                "ObjectType": obj_type,
                "PredefinedType": predefined_type,
                "Level": level_name,
                "Width": w,
                "Height": h,
                "Space 1": space_1,
                "Space 2": space_2,
            }
        )

    df = pd.DataFrame(rows)

    # Ensure consistent columns even when empty
    wanted_cols = [
        "Category",
        "GlobalId",
        "Name",
        "Tag",
        "Type",
        "ObjectType",
        "PredefinedType",
        "Level",
        "Width",
        "Height",
        "Space 1",
        "Space 2",
    ]
    for c in wanted_cols:
        if c not in df.columns:
            df[c] = ""
    df = df[wanted_cols]

    # Basic meta / QC counts
    meta = {
        "length_unit_scale_to_m": scale_to_m,
        "unit_out": options.out_unit,
        "count_total": len(df),
        "count_doors": int((df["Category"] == "Door").sum()) if len(df) else 0,
        "count_windows": int((df["Category"] == "Window").sum()) if len(df) else 0,
        "missing_width": int(df["Width"].isna().sum()) if len(df) else 0,
        "missing_height": int(df["Height"].isna().sum()) if len(df) else 0,
    }
    return df, meta


