class Parametrization(vkt.Parametrization):
    page = vkt.Page("Door & Window Schedule", views=["ifc_view", "schedule_table", "summary_view"])

    page.tab_inputs = vkt.Tab("Inputs")
    page.tab_inputs.inputs = vkt.Section("Upload & options")
    page.tab_inputs.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Door & Window Schedule (IFC)

            Upload an IFC file and generate a door/window schedule for design documentation or quantity take-offs.

            **Notes**
            - Dimensions are read from `OverallWidth/OverallHeight` and/or quantity take-off sets (Qto) when available.
            - Level is derived from the spatial container (typically an `IfcBuildingStorey`).
            - Room/space adjacency is derived from `IfcRelSpaceBoundary` (if present in the export).
            """
        )
    )

    page.tab_inputs.inputs.ifc_file = vkt.FileField(
        "IFC file (.ifc or .ifczip)",
        file_types=[".ifc", ".ifczip", ".zip"],
    )

    page.tab_inputs.inputs.include_what = vkt.OptionField(
        "Include",
        options=["Doors & Windows", "Doors only", "Windows only"],
        default="Doors & Windows",
        variant="radio-inline",
    )

    page.tab_inputs.inputs.out_unit = vkt.OptionField(
        "Output length unit",
        options=["Model", "mm", "m", "ft"],
        default="Model",
        description="If set to 'Model', values are shown in the IFC project length unit.",
    )

    page.tab_inputs.inputs.include_spaces = vkt.BooleanField(
        "Include adjacent rooms/spaces (IfcRelSpaceBoundary)",
        default=True,
        description="May be empty if the IFC export did not include space boundaries.",
    )


class Controller(vkt.Controller):
    label = "Door & Window Schedule"
    parametrization = Parametrization(width=55)

    def _require_ifc(self, params: Parametrization) -> vkt.File:
        file_field_val = params.page.tab_inputs.inputs.ifc_file
        vf = _as_viktor_file(file_field_val)
        if not vf:
            raise vkt.UserError("Please upload an IFC file.")
        return vf

    def _get_schedule(self, params: Parametrization) -> Tuple[pd.DataFrame, Dict[str, Any]]:
        vf = self._require_ifc(params)
        raw = _get_file_bytes(vf)
        ifc_bytes = _extract_ifc_bytes(raw)

        opts = ScheduleOptions(
            include_spaces=bool(params.page.tab_inputs.inputs.include_spaces),
            out_unit=str(params.page.tab_inputs.inputs.out_unit),
        )
        return _get_doors_and_windows_schedule(ifc_bytes, options=opts)

    @vkt.IFCView("IFC model", duration_guess=1)
    def ifc_view(self, params: Parametrization, **kwargs) -> vkt.IFCResult:
        vf = self._require_ifc(params)
        return vkt.IFCResult(vf)

    @vkt.TableView("Schedule", duration_guess=5)
    def schedule_table(self, params: Parametrization, **kwargs) -> vkt.TableResult:
        df, _meta = self._get_schedule(params)

        include_what = params.page.tab_inputs.inputs.include_what
        if include_what == "Doors only":
            df = df[df["Category"] == "Door"]
        elif include_what == "Windows only":
            df = df[df["Category"] == "Window"]

        # Friendly column headers with unit
        u = params.page.tab_inputs.inputs.out_unit
        width_header = "Width" if u == "Model" else f"Width [{u}]"
        height_header = "Height" if u == "Model" else f"Height [{u}]"
        df = df.rename(columns={"Width": width_header, "Height": height_header})

        # Sort by Level then Category then Name (typical schedule layout)
        sort_cols = [c for c in ["Level", "Category", "Name"] if c in df.columns]
        if sort_cols:
            df = df.sort_values(sort_cols, kind="stable")

        return vkt.TableResult(df)

    @vkt.DataView("Summary", duration_guess=1)
    def summary_view(self, params: Parametrization, **kwargs) -> vkt.DataResult:
        df, meta = self._get_schedule(params)

        include_what = params.page.tab_inputs.inputs.include_what
        if include_what == "Doors only":
            df2 = df[df["Category"] == "Door"]
        elif include_what == "Windows only":
            df2 = df[df["Category"] == "Window"]
        else:
            df2 = df

        # Recompute some counts after filtering
        count_total = len(df2)
        count_doors = int((df2["Category"] == "Door").sum()) if count_total else 0
        count_windows = int((df2["Category"] == "Window").sum()) if count_total else 0

        missing_w = int(df2["Width"].isna().sum()) if count_total else 0
        missing_h = int(df2["Height"].isna().sum()) if count_total else 0

        level_count = int(df2["Level"].nunique()) if count_total else 0

        data = vkt.DataGroup(
            vkt.DataItem("Elements in table", count_total),
            vkt.DataItem("Doors", count_doors),
            vkt.DataItem("Windows", count_windows),
            vkt.DataItem("Unique levels", level_count),
            vkt.DataItem("Missing width values", missing_w),
            vkt.DataItem("Missing height values", missing_h),
            vkt.DataItem("Output unit", str(meta.get("unit_out", ""))),
        )
        return vkt.DataResult(data)
